def main():
    S = input()

    # Count occurrences of each character in S
    char_count = {}
    for char in S:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Create a dictionary to map each occurrence count to the number of characters with that count
    count_frequency = {}
    for count in char_count.values():
        if count in count_frequency:
            count_frequency[count] += 1
        else:
            count_frequency[count] = 1

    # Check if all values in count_frequency are either zero or two
    for value in count_frequency.values():
        if value != 2:
            print('No')
            return

    print('Yes')
